{
    method:native ? "POST" : "PATCH", url:native ? "/native/catalog/menu-categories/:categoryCode" : "/catalog/menu-categories/:categoryCode", handler:
    async (request, reply) =>
      handleRoute(reply, async () => {
        const context = await resolveStaffContext(options, request);
        const categoryCode = requiredCode(request.params.categoryCode, "categoryCode");
        const input=readJsonObject(request.body,"请求正文");
        const expected=native ? requiredText(input.expectedUpdatedAt,"expectedUpdatedAt",100) : null;
        const patch = readUpdateMenuCategory(native ? input.patch : request.body);
        const idempotencyKey = readIdempotencyKey(request);
        const command = menuCategoryCommand(
          request,
          context,
          "catalog.menu-category.update",
          idempotencyKey,
          { categoryCode, ...patch, ...(native ? {expectedUpdatedAt:expected} : {}) },
        );
        const executor = catalogWriteExecutor(options.commandExecutor, context, native, tx => assertLivePermission(tx, context.employeeId, CATALOG_PRODUCT_MANAGE_PERMISSION));
        const execution = await executor.execute(
          command,
          async (transaction) => {
            await assertLivePermission(
              transaction,
              context.employeeId,
              CATALOG_PRODUCT_MANAGE_PERMISSION,
            );
            const before = await getMenuCategoryByCode(transaction, categoryCode, true);
            if(native && before.updatedAt!==expected)throw new NativePhysicalNotCommittedError('分类已变化，本次未提交，请刷新原分类');
            const afterInput = {
              displayName: patch.displayName ?? before.displayName,
              parentCode: patch.parentCode === undefined ? before.parentCode : patch.parentCode,
              sortOrder: patch.sortOrder ?? before.sortOrder,
              guestVisible: patch.guestVisible ?? before.guestVisible,
            };
            await assertMenuCategoryParent(
              transaction,
              afterInput.parentCode,
              before.code,
            );
            await assertMenuCategoryStructure(
              transaction,
              before,
              afterInput.parentCode,
              afterInput.guestVisible,
            );
            await transaction.query(`
              UPDATE mbox.menu_categories
              SET display_name=$4::text,
                  parent_code=$5::text,
                  sort_order=$6::integer,
                  guest_visible=$7::boolean,
                  updated_at=clock_timestamp()
              WHERE tenant_id=$1::uuid AND store_id=$2::uuid AND id=$3::uuid
            `, [
              transaction.scope.tenantId,
              transaction.scope.storeId,
              before.id,
              afterInput.displayName,
              afterInput.parentCode,
              afterInput.sortOrder,
              afterInput.guestVisible,
            ]);
            const category = await getMenuCategory(transaction, before.id);
            return menuCategoryOutcome(
              request,
              context,
              idempotencyKey,
              "catalog.menu-category.updated",
              "catalog.menu-category.updated.v1",
              category,
              before,
            );
          },
        );
        return reply.send(executionResponse(execution));
      }),
  }

{
    method:options.nativeProtocol ? "POST" : "PUT",url:"/inventory/products/:productId/recipe",handler:async (request, reply) =>
      handleRoute(reply, async () => {
        const context = await options.resolveContext(request);
        const body = readObject(request.body);
        const components = readArray(body.components, "components", 100).map(
          (raw) => {
            const component = readObject(raw);
            return {
              inventoryItemId: readUuid(
                component.inventoryItemId,
                "inventoryItemId",
              ),
              quantity: readDecimal(component.quantity, "quantity", false),
              expectedWasteQuantity: readDecimal(
                component.expectedWasteQuantity ?? "0",
                "expectedWasteQuantity",
                true,
              ),
            };
          },
        );
        const input: ReplaceRecipeInput = {
          productId: readUuid(request.params.productId, "productId"),
          yieldQuantity: readInteger(
            body.yieldQuantity ?? 1,
            "yieldQuantity",
            1,
            1000,
          ),
          instructionsSnapshot: readJsonObject(
            body.instructionsSnapshot ?? {},
            "instructionsSnapshot",
          ),
          components,
        };
        const execution = await execute(
          options,
          context,
          request,
          "inventory.recipe.replace",
          "inventory.manage",
          codec<{ id: string; version: number }>(),
          async (transaction) => {
            if(options.nativeProtocol){
              await transaction.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))',[`inventory-recipe:${context.scope.tenantId}:${context.scope.storeId}:${input.productId}`]);
              const product=(await transaction.query('SELECT id,name,product_kind,inventory_control_mode,updated_at::text FROM mbox.products WHERE tenant_id=$1 AND store_id=$2 AND id=$3 FOR UPDATE',[context.scope.tenantId,context.scope.storeId,input.productId])).rows[0];
              const original=await readActiveRecipe(transaction,context.employeeId,input.productId);
              if(!product||product.product_kind!=='single')throw new InventoryConflictError('配方只用于原单品，套餐请编辑组成商品');
              if(typeof body.expectedVersion!=='string'||body.expectedVersion!==nativeRecipeVersion(original,product))throw new InventoryConflictError('原配方或商品已修改，本次未提交，请刷新核对');
            }
            const inventory = createInventory(transaction);
            const recipe = await inventory.replaceActiveRecipe(input);
            await inventory.synchronizeTrackedRecipeCostsForInventoryItems(
              components.map((component) => component.inventoryItemId),
              context.employeeId,
              "配方更新后按当前移动加权库存成本自动重算",
            );
            return recipe;
          },
        );
        return reply.send(response(execution));
      }),
  }

{
    method: ['GET', 'HEAD'], url: `${PREFIX}/*`,
    async handler(request, reply) {
      const name = request.params['*']
      const manifest = name === 'stable.json' || name === 'preview.json'
      if (directory === null || (!manifest && (!APK.test(name) || name.includes('..')))) return missing(reply)
      const root = resolve(directory)
      let file: Awaited<ReturnType<typeof open>> | undefined
      try {
        const rootStat = await lstat(root)
        if (!rootStat.isDirectory() || rootStat.isSymbolicLink() || await realpath(root) !== root) return missing(reply)
        // O_NOFOLLOW prevents a swap of a checked public filename to a symlink.
        file = await open(join(root, name), constants.O_RDONLY | constants.O_NOFOLLOW)
        const stat = await file.stat()
        if (!stat.isFile() || stat.size <= 0 || stat.size > (manifest ? 65_536 : MAX_APK_BYTES)) return missing(reply)
        reply.header('x-content-type-options', 'nosniff')
        if (manifest) {
          const bytes = await file.readFile()
          const feed: unknown = JSON.parse(bytes.toString('utf8'))
          if (typeof feed !== 'object' || feed === null || !('schemaVersion' in feed) || feed.schemaVersion !== 1
            || !('channel' in feed) || feed.channel !== name.slice(0, -5) || !('releases' in feed) || !Array.isArray(feed.releases)) return missing(reply)
          return reply.header('cache-control', 'no-store').type('application/json; charset=utf-8')
            .header('content-length', bytes.length).send(request.method === 'HEAD' ? undefined : bytes)
        }
        reply.type('application/vnd.android.package-archive')
          .header('cache-control', 'public, max-age=31536000, immutable')
          .header('content-length', stat.size)
          .header('etag', `"${name}"`)
        if (request.method === 'HEAD') return reply.send()
        const stream = file.createReadStream({ autoClose: true })
        file = undefined // The response stream now owns this descriptor.
        return reply.send(stream)
      } catch (error) {
        const code = (error as NodeJS.ErrnoException).code
        if (code === 'ENOENT' || code === 'ENOTDIR' || code === 'ELOOP' || error instanceof SyntaxError) return missing(reply)
        request.log.error({ err: error }, 'native update file could not be read')
        return reply.header('cache-control', 'no-store').code(503).send({ error: { code: 'NATIVE_UPDATE_UNAVAILABLE', message: '更新文件暂时无法读取' } })
      } finally {
        await file?.close()
      }
    },
  }

{
    method: ['POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'], url,
    handler: (_request, reply) => reply.header('allow', 'GET, HEAD').header('cache-control', 'no-store')
      .code(405).send({ error: { code: 'NATIVE_UPDATE_READ_ONLY', message: '更新文件仅供读取' } }),
  }
